<?php
require_once __DIR__ . '/../../admin/implements/conexion.php';exigirAdmin();$sql="SELECT p.*,u.nombre usuario,l.titulo libro,DATEDIFF(CURDATE(),p.fecha_devolucion) dias_atraso FROM prestamos p JOIN usuarios u ON u.id_usuario=p.id_usuario JOIN libros l ON l.id_libro=p.id_libro WHERE p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE() ORDER BY p.fecha_devolucion";$rows=$pdo->query($sql)->fetchAll();iniciarPagina('Atrasos');barraNavegacion('atrasos.php');
?>
<div class="encabezado-pagina"><div><span class="sobrelinea">SEGUIMIENTO</span><h1>Préstamos atrasados</h1><p>Préstamos activos que superaron su fecha límite.</p></div><span class="badge text-bg-danger fs-6"><?= count($rows); ?> atrasados</span></div><section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Fecha préstamo</th><th>Fecha límite</th><th>Días atraso</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr class="table-danger"><td><?= escapar($p['usuario']); ?></td><td><?= escapar($p['libro']); ?></td><td><?= escapar($p['fecha_prestamo']); ?></td><td><?= escapar($p['fecha_devolucion']); ?></td><td><?= (int)$p['dias_atraso']; ?></td><td><span class="badge text-bg-danger">Atrasado</span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="text-center">No hay préstamos atrasados.</td></tr><?php endif; ?></tbody></table></div></section><?php finPagina(); ?>
